import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Cluster.
 *
 * @stability experimental
 */
export interface IClusterRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Cluster resource.
     */
    readonly clusterRef: ClusterReference;
}
/**
 * A reference to a Cluster resource.
 *
 * @struct
 * @stability external
 */
export interface ClusterReference {
    /**
     * The ClusterArn of the Cluster resource.
     */
    readonly clusterArn: string;
}
/**
 * Indicates that this resource can be referenced as a ClusterSnapshot.
 *
 * @stability experimental
 */
export interface IClusterSnapshotRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a ClusterSnapshot resource.
     */
    readonly clusterSnapshotRef: ClusterSnapshotReference;
}
/**
 * A reference to a ClusterSnapshot resource.
 *
 * @struct
 * @stability external
 */
export interface ClusterSnapshotReference {
    /**
     * The SnapshotArn of the ClusterSnapshot resource.
     */
    readonly snapshotArn: string;
}
